const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const steps = [["paint", 40], ["dry", 10]];

const last = steps.reduce(async (previous, [name, ms]) => {
  await delay(ms);
  console.log(name + " ready");
  await previous;
  console.log(name + " done");
}, Promise.resolve());

last.then(() => console.log("all done"));
